from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

_CENT = Decimal("0.01")
_FOUR = Decimal("0.0001")
_TYPES = {"PURCHASE", "SALE", "CUSTOMER_RETURN", "PURCHASE_RETURN"}


def _prec_for_target(value, target_exp):
    try:
        if not isinstance(value, Decimal):
            return 28
        if value.is_zero():
            return 28
        tup = value.as_tuple()
        d = len(tup.digits)
        adj = tup.exponent + d - 1
        needed = adj - target_exp + 1
        if needed < d:
            needed = d
        if needed < 1:
            needed = 1
        need = needed + 10
        if need < 28:
            need = 28
        return need
    except Exception:
        return 28


def _quantize_cent(value):
    need = _prec_for_target(value, -2)
    with localcontext() as ctx:
        ctx.prec = need
        return value.quantize(_CENT, rounding=ROUND_HALF_UP)


def _quantize_four(value):
    need = _prec_for_target(value, -4)
    with localcontext() as ctx:
        ctx.prec = need
        return value.quantize(_FOUR, rounding=ROUND_HALF_UP)


def _d2(value):
    return _quantize_cent(value)


def _q4(value):
    return _quantize_four(value)


def _div50(a, b):
    with localcontext() as ctx:
        ctx.prec = 50
        return a / b


def _product_cents(a, qty):
    # exact (a * qty) quantized to cents; a is Decimal, qty is int
    if isinstance(a, Decimal):
        da = len(a.as_tuple().digits)
    else:
        da = 28
    dq = len(str(abs(qty))) if qty != 0 else 1
    need_op = da + dq + 10
    if need_op < 28:
        need_op = 28
    with localcontext() as ctx:
        ctx.prec = need_op
        prod = a * qty
    return _quantize_cent(prod)


def _purchase_cents(cost, qty):
    da = len(cost.as_tuple().digits)
    dq = len(str(abs(qty))) if qty != 0 else 1
    need_op = da + dq + 10
    if need_op < 28:
        need_op = 28
    with localcontext() as ctx:
        ctx.prec = need_op
        prod = cost * qty
    return _quantize_cent(prod)


def _add_cents(a, b):
    need_op = max(len(a.as_tuple().digits), len(b.as_tuple().digits)) + 10
    if need_op < 28:
        need_op = 28
    # ensure enough for exponent spread (both should be exponent -2)
    need_op = max(need_op, _prec_for_target(a, -2), _prec_for_target(b, -2))
    with localcontext() as ctx:
        ctx.prec = need_op
        s = a + b
    return _quantize_cent(s)


def _sub_cents(a, b):
    need_op = max(len(a.as_tuple().digits), len(b.as_tuple().digits)) + 10
    if need_op < 28:
        need_op = 28
    need_op = max(need_op, _prec_for_target(a, -2), _prec_for_target(b, -2))
    with localcontext() as ctx:
        ctx.prec = need_op
        s = a - b
    return _quantize_cent(s)


def process_inventory(movements: list[dict]) -> dict:
    if not isinstance(movements, list):
        raise ValueError("movements must be a list")
    qty = 0
    value = Decimal("0.00")
    total_cogs = Decimal("0.00")
    total_pr = Decimal("0.00")
    for mv in movements:
        if not isinstance(mv, dict):
            raise ValueError("movement must be a dict")
        mtype = mv.get("type")
        if not isinstance(mtype, str) or mtype not in _TYPES:
            raise ValueError(f"invalid movement type: {mtype!r}")
        quantity = mv.get("quantity")
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("quantity must be a positive int")
        if mtype == "PURCHASE":
            if "unit_cost" not in mv:
                raise ValueError("unit_cost required for PURCHASE")
            raw = mv["unit_cost"]
            if not isinstance(raw, str):
                raise ValueError("unit_cost must be a string")
            try:
                cost = Decimal(raw)
            except (InvalidOperation, ValueError):
                raise ValueError(f"invalid unit_cost: {raw!r}") from None
            if not cost.is_finite() or cost < 0:
                raise ValueError("unit_cost must be finite and >= 0")
            added = _purchase_cents(cost, quantity)
            value = _add_cents(value, added)
            qty += quantity
        elif mtype == "SALE":
            if quantity > qty:
                raise ValueError("sale exceeds quantity on hand")
            avg = _div50(value, qty)
            cogs = _product_cents(avg, quantity)
            value = _sub_cents(value, cogs)
            qty -= quantity
            total_cogs = _add_cents(total_cogs, cogs)
        elif mtype == "CUSTOMER_RETURN":
            if qty == 0:
                raise ValueError("no current average cost for customer return")
            avg = _div50(value, qty)
            added = _product_cents(avg, quantity)
            value = _add_cents(value, added)
            qty += quantity
        else:  # PURCHASE_RETURN
            if quantity > qty:
                raise ValueError("purchase return exceeds quantity on hand")
            avg = _div50(value, qty)
            removed = _product_cents(avg, quantity)
            value = _sub_cents(value, removed)
            qty -= quantity
            total_pr = _add_cents(total_pr, removed)
    if qty == 0:
        avg_out = Decimal("0.0000")
    else:
        raw_avg = _div50(value, qty)
        avg_out = _q4(raw_avg)
    return {
        "quantity_on_hand": qty,
        "inventory_value": _d2(value),
        "average_cost": avg_out,
        "total_cogs": _d2(total_cogs),
        "total_purchase_returns": _d2(total_pr),
    }
